from typing import List

def count_islands(grid: List[str]) -> int:
    if not grid:
        return 0

    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0

    visited = [[False for _ in range(cols)] for _ in range(rows)]

    def dfs(i, j):
        visited[i][j] = True
        directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
        for dx, dy in directions:
            ni, nj = i + dx, j + dy
            if 0 <= ni < rows and 0 <= nj < cols and not visited[ni][nj]:
                dfs(ni, nj)

    island_count = 0

    for i in range(rows):
        for j in range(cols):
            if not visited[i][j]:
                island_count += 1
                dfs(i, j)

    return island_count
